def style_body(p):
    p.paragraph_format.first_line_indent = Pt(21)
    p.paragraph_format.line_spacing = Pt(20)
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after = Pt(0)
    for r in p.runs:
        r.font.size = Pt(10.5)
        r.font.name = "Times New Roman"
        r._element.rPr.rFonts.set(qn("w:eastAsia"), "\u5b8b\u4f53")


def count_chars(doc: Document):
    parts = [p.text for p in doc.paragraphs]
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                parts.append(cell.text)
    text = "\n".join(parts)
    return len(re.findall(r"[\u4e00-\u9fff]", text)), len(re.sub(r"\s+", "", text)), text


def main() -> None:
    shutil.copy2(SRC, OUT)
    doc = Document(str(OUT))

    for i, p in enumerate(doc.paragraphs):
        t = p.text.strip()
        if t == "\u6458  \u8981" and i + 1 < len(doc.paragraphs):
            doc.paragraphs[i + 1].text = ABSTRACT_CN
            style_body(doc.paragraphs[i + 1])
        elif t == "Abstract" and i + 1 < len(doc.paragraphs):
            doc.paragraphs[i + 1].text = ABSTRACT_EN
            style_body(doc.paragraphs[i + 1])
        elif p.text in REPLACEMENTS:
            p.text = REPLACEMENTS[p.text]
            style_body(p)

    # Ensure Chapter 5 concentrates concrete framework/tool names and React.
    for i, p in enumerate(doc.paragraphs):
        if p.text.strip().startswith("5.1 "):
            for q in doc.paragraphs[i + 1 :]:
                if q.style.name.startswith("Heading"):
                    break
                if "平台技术栈包括" in q.text:
                    if "React" not in q.text:
                        q.text = q.text.replace("Web 前端", "React Web 前端")
                    style_body(q)
                if "该技术栈的选型" in q.text and CH5_APPEND not in q.text:
                    q.text = q.text + CH5_APPEND
                    style_body(q)
                    break

    doc.save(str(OUT))
    cn, nonspace, text = count_chars(doc)
    print(f"output={OUT}")
    print(f"cn_chars={cn}")
    print(f"nonspace_chars={nonspace}")
    for k in ["MinerU", "BGE-M3", "Milvus", "MongoDB", "Redis", "FastAPI", "LangChain", "LangGraph", "Qwen", "React"]:
        print(f"{k}={text.count(k)}")


if __name__ == "__main__":
    main()
